package com.wildfire.client.music;
import com.mojang.blaze3d.platform.NativeImage;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.renderer.RenderPipelines;import net.minecraft.client.renderer.texture.DynamicTexture;import net.minecraft.resources.Identifier;import java.net.URI;import java.net.http.*;import java.time.Duration;import java.util.*;import java.util.concurrent.*;
public final class StreamPreviewCache {private record Image(Identifier id,int width,int height){}private static final HttpClient HTTP=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(4)).followRedirects(HttpClient.Redirect.NORMAL).build();private static final Map<String,Image> READY=new ConcurrentHashMap<>();private static final Set<String> LOADING=ConcurrentHashMap.newKeySet();private StreamPreviewCache(){}public static void draw(GuiGraphicsExtractor g,String raw,int x,int y,int w,int h){if(raw==null||raw.isBlank())return;Image image=READY.get(raw);if(image==null){load(raw);return;}double scale=Math.min(w/(double)image.width,h/(double)image.height);int dw=Math.max(1,(int)(image.width*scale)),dh=Math.max(1,(int)(image.height*scale));g.blit(RenderPipelines.GUI_TEXTURED,image.id,x+(w-dw)/2,y+(h-dh)/2,0,0,dw,dh,image.width,image.height,image.width,image.height);}private static void load(String raw){if(!LOADING.add(raw)||READY.size()>=8)return;CompletableFuture.runAsync(()->{try{URI uri=URI.create(raw);if(!allowed(uri))return;var response=HTTP.send(HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(7)).header("User-Agent","SpringPlusCosmetics/1").GET().build(),HttpResponse.BodyHandlers.ofInputStream());if(response.statusCode()/100!=2)return;byte[] bytes;try(var in=response.body()){bytes=in.readNBytes(2_000_001);}if(bytes.length==0||bytes.length>2_000_000)return;NativeImage pixels=NativeImage.read(bytes);if(pixels.getWidth()<16||pixels.getHeight()<9||pixels.getWidth()>1920||pixels.getHeight()>1080){pixels.close();return;}Minecraft.getInstance().execute(()->{if(READY.size()>=8){pixels.close();return;}Identifier id=Identifier.fromNamespaceAndPath("appearance_sync","stream_preview/"+Integer.toUnsignedString(raw.hashCode(),36));var texture=new DynamicTexture(()->"Stream preview",pixels);Minecraft.getInstance().getTextureManager().register(id,texture);texture.upload();READY.put(raw,new Image(id,pixels.getWidth(),pixels.getHeight()));});}catch(Exception ignored){}finally{LOADING.remove(raw);}});}private static boolean allowed(URI uri){if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null)return false;String h=uri.getHost().toLowerCase(Locale.ROOT);return h.endsWith("jtvnw.net")||h.endsWith("twitch.tv")||h.endsWith("ytimg.com")||h.endsWith("googleusercontent.com")||h.endsWith("tiktokcdn.com")||h.endsWith("kick.com")||h.endsWith("cloudfront.net");}}
